-- сохранить полный исходный аудит сопоставления событий и партий.
WITH s AS (SELECT topic,kafka_partition,kafka_offset,original_batch_id,coalesced_batch_id FROM {{source:oil_stg__batch_coalesce_event_map}}), t AS (SELECT topic,kafka_partition,kafka_offset,original_batch_id,coalesced_batch_id FROM {{target:oil_stg__batch_coalesce_event_map}}), d AS ((SELECT * FROM s EXCEPT ALL SELECT * FROM t) UNION ALL (SELECT * FROM t EXCEPT ALL SELECT * FROM s)) SELECT count(*) AS n FROM d;
